static DWORD findpid(void){HANDLE s=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);PROCESSENTRY32W e={0};DWORD r=0;e.dwSize=sizeof(e);if(s!=INVALID_HANDLE_VALUE&&Process32FirstW(s,&e))do{if(!_wcsicmp(e.szExeFile,L"game.exe")){HANDLE h=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,e.th32ProcessID);wchar_t q[MAX_PATH];DWORD n=MAX_PATH;if(h&&QueryFullProcessImageNameW(h,0,q,&n)&&!_wcsicmp(q,path))r=e.th32ProcessID;if(h)CloseHandle(h);}}while(!r&&Process32NextW(s,&e));if(s!=INVALID_HANDLE_VALUE)CloseHandle(s);return r;}
int wmain(void){DWORD id=findpid();if(!id)return 2;HANDLE p=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ|PROCESS_VM_OPERATION|PROCESS_VM_WRITE,FALSE,id);if(!p)return 3;DWORD root=0,ptr=0,cd=0;SIZE_T n=0;if(!ReadProcessMemory(p,(void*)0x00A35DB4,&root,4,&n)||n!=4)return 4;const DWORD po[]={0x52D8,0x52DC,0x52E0,0x52E4,0x52E8};const wchar_t* names[]={L"飞机",L"步兵",L"车辆",L"船只",L"建筑"};int done=0;for(int i=0;i<5;i++){if(!ReadProcessMemory(p,(void*)(uintptr_t)(root+po[i]),&ptr,4,&n)||n!=4||!ptr)continue;if(!ReadProcessMemory(p,(void*)(uintptr_t)(ptr+0x24),&cd,4,&n)||n!=4||cd>=54)continue;DWORD v=53;SIZE_T w=0;if(WriteProcessMemory(p,(void*)(uintptr_t)(ptr+0x24),&v,4,&w)&&w==4){wprintf(L"%ls queue=0x%08lX cd=%lu -> 53\n",names[i],(unsigned long)ptr,(unsigned long)cd);done++;}}wprintf(L"INSTANT_ALL completed=%d\n",done);CloseHandle(p);return done?0:5;}
